mapper.select:


    deleted = 0
     and title like concat('%', #{title}, '%')
     and clazz_id = #{clazzId}
     and teacher_id = #{teacherId}
     and course_date = #{courseDate}
     and start_time like concat('%', #{startTime}, '%')
     and end_time like concat('%', #{endTime}, '%')
     and content like concat('%', #{content}, '%')
     and status = #{status}

order by id desc
